import fs from "node:fs";
import path from "node:path";

const BLOG_DIR = path.resolve(process.cwd(), "content", "blog");
const OUT_FILE = path.resolve(process.cwd(), "lib", "blog-bundle.generated.ts");

function run() {
  const entries = {};

  if (fs.existsSync(BLOG_DIR)) {
    const files = fs
      .readdirSync(BLOG_DIR)
      .filter((file) => file.endsWith(".mdx") || file.endsWith(".md"))
      .sort((a, b) => a.localeCompare(b));

    for (const file of files) {
      entries[file] = fs.readFileSync(path.join(BLOG_DIR, file), "utf8");
    }
  }

  const content =
    "// Auto-generated by scripts/sync-blog-bundle.mjs — do not edit manually.\n" +
    "// Ensures blog posts remain readable in Cloudflare Workers (no runtime filesystem).\n" +
    `export const BUNDLED_BLOG_FILES: Readonly<Record<string, string>> = ${JSON.stringify(entries, null, 2)};\n`;

  fs.writeFileSync(OUT_FILE, content, "utf8");
  console.log(
    `[blog-bundle] Synced ${Object.keys(entries).length} blog file(s) -> lib/blog-bundle.generated.ts`,
  );
}

run();
